/***********************
 * Shared utility functions for cross-runtime testing.
 ***********************/
export function deepEquals(a, b, seen = new WeakSet()) {
    if (a === b)
        return true;
    if (a === null || b === null)
        return a === b;
    if (typeof a !== typeof b)
        return false;
    if (typeof a !== "object")
        return a === b;
    if (Array.isArray(a) || Array.isArray(b)) {
        if (!Array.isArray(a) || !Array.isArray(b))
            return false;
        if (a.length !== b.length)
            return false;
        return a.every((val, i) => deepEquals(val, b[i], seen));
    }
    const aObj = a;
    const bObj = b;
    if (seen.has(aObj))
        return true;
    seen.add(aObj);
    const aKeys = Object.keys(aObj);
    const bKeys = Object.keys(bObj);
    if (aKeys.length !== bKeys.length)
        return false;
    const aRec = a;
    const bRec = b;
    return aKeys.every((key) => deepEquals(aRec[key], bRec[key], seen));
}
/** Serialize unknown values safely for test output. */
export function safeStringify(value) {
    try {
        return JSON.stringify(value);
    }
    catch (_) {
        /* expected: value may contain circular references or non-serializable types */
        if (value === null)
            return "null";
        if (value === undefined)
            return "undefined";
        if (typeof value === "function")
            return "[Function]";
        if (typeof value === "object")
            return `[${value.constructor?.name ?? "Object"}]`;
        return String(value);
    }
}
